SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
BEGIN;

DROP TABLE IF EXISTS product_holding;
CREATE TABLE product_holding (
    holding_id BIGINT,
    cif TEXT,
    product_category TEXT,
    product_code TEXT,
    product_name TEXT,
    status TEXT,
    opened_date DATE,
    branch_id TEXT,
    department_id TEXT,
    portfolio_id TEXT,
    source_system TEXT,
    PRIMARY KEY (holding_id)
);
COMMIT;
